SELECT TOP (0) [hypothesis_id], [investigation_id], [analysis_perspective], [hypothesis_title], [hypothesis_statement_markdown], [reasoning_markdown], [confidence_score], [supporting_evidence_codes_json], [contradicting_evidence_codes_json], [proposed_fix_json], [fix_risk_level], [matched_runbook_id], [is_leading_hypothesis], [display_order], [created_at] INTO #demo_rows FROM [keigan].[investigation_hypothesis];
INSERT INTO #demo_rows ([hypothesis_id], [investigation_id], [analysis_perspective], [hypothesis_title], [hypothesis_statement_markdown], [reasoning_markdown], [confidence_score], [supporting_evidence_codes_json], [contradicting_evidence_codes_json], [proposed_fix_json], [fix_risk_level], [matched_runbook_id], [is_leading_hypothesis], [display_order], [created_at]) VALUES
    (N'00000000-0000-4000-8000-0000000002ca', N'00000000-0000-4000-8000-0000000002af', N'application', N'A memory leak in the document renderer', N'Memory in the document renderer grows steadily until the container limit is reached, which points at unreleased buffers in the application. This is the underlying defect. [E4]', N'1. Memory climbs steadily across the window rather than spiking [E4]. 2. A leak explains why restarts help only temporarily. The code location is not identified in the knowledge base.', 0.55, N'["E4"]', N'[]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 0, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000002cb', N'00000000-0000-4000-8000-0000000002af', N'dependencies', N'A dependency causing 502 responses at the gateway', N'The 502 responses originate at the gateway because backend pods restart; no dependency fails first. [E19]', N'1. Gateway errors follow the pod restarts in time. 2. No dependency shows its own failures first.', 0.18, N'[]', N'[]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 1, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000002cc', N'00000000-0000-4000-8000-0000000002af', N'infrastructure', N'Containers hit their 1 GiB memory limit and are OOMKilled', N'Containers of claims-document-renderer reach their 1 GiB limit, are OOMKilled, back off and restart, so the gateway intermittently returns 502. [E4]', N'1. OOMKilled events and BackOff restarts are new. 2. Memory working set approaches the limit [E4]. 3. Restart counters rose in the same minutes. Timing aligns with the 502s.', 0.82, N'["E4"]', N'[]', N'{"summary": "Relieve memory pressure with a temporary limit increase and restart; fix the renderer''s unreleased image buffers.", "steps": [{"description": "Confirm which pods are close to the limit (read-only).", "command_text": "kubectl top pods -n claims-docs", "command_language": "bash", "command_risk_level": "low"}, {"description": "Temporarily raise the memory limit of claims-document-renderer to 2Gi.", "command_text": "kubectl set resources deployment/claims-document-renderer -n claims-docs --limits=memory=2Gi", "command_language": "bash", "command_risk_level": "medium"}, {"description": "Restart the deployment to clear leaked memory.", "command_text": "kubectl rollout restart deployment/claims-document-renderer -n claims-docs", "command_language": "bash", "command_risk_level": "medium"}, {"description": "Durable fix: release image buffers after each render and add a memory-based alert at 80 percent of the limit.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [{"repository_name": "claims-document-renderer", "file_path": "file not identified", "change_description": "Dispose image buffers after each render.", "before_snippet": "var bitmap = Render(document);\nreturn bitmap.ToPng();", "after_snippet": "using var bitmap = Render(document);\nreturn bitmap.ToPng();"}], "verification_steps": ["kubectl get pods -n claims-docs shows no new OOMKilled restarts for 30 minutes.", "Gateway 502 rate returns to baseline."], "rollback_steps": ["kubectl rollout undo deployment/claims-document-renderer -n claims-docs  # if the restart makes things worse"]}', N'medium', N'00000000-0000-4000-8000-00000000009c', 1, 2, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000002eb', N'00000000-0000-4000-8000-0000000002de', N'application', N'A code or configuration change broke TLS calls', N'No release or configuration change is visible near onset, so an application change is unlikely.', N'1. No deployment near the first error. 2. Errors are TLS validation failures, not application exceptions.', 0.3, N'[]', N'[]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 0, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000002ec', N'00000000-0000-4000-8000-0000000002de', N'dependencies', N'The mutual-TLS client certificate for the policy core system expired at 00:00 UTC', N'Every call to the policy core system fails the TLS handshake because the client certificate expired at 00:00 UTC. [E2]', N'1. Errors state that the certificate expired [E2]. 2. The pattern is new and appears at exactly 00:00 UTC. 3. Failure ratio is above 60 percent across operations calling the same dependency.', 0.88, N'["E2"]', N'[]', N'{"summary": "Rotate the expired mutual-TLS client certificate and restart the dependent services so they load it.", "steps": [{"description": "Confirm the expiry date of the certificate presented to policy-core (read-only).", "command_text": "openssl s_client -connect policy-core.internal.example:443 -servername policy-core.internal.example </dev/null 2>/dev/null | openssl x509 -noout -enddate", "command_language": "bash", "command_risk_level": "low"}, {"description": "Issue a replacement certificate and import it into Key Vault (vault and certificate names are not recorded in the knowledge base; confirm them with the platform team).", "command_text": null, "command_language": null, "command_risk_level": null}, {"description": "Restart the app service channel-gateway-app.", "command_text": "az webapp restart --name channel-gateway-app --resource-group RG_14470_AUCHAD_PRD01", "command_language": "bash", "command_risk_level": "medium"}, {"description": "Durable fix: add a certificate-expiry alert at 30, 14 and 7 days and automate rotation.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["TLS handshake errors disappear from the logs.", "Channel API availability returns above 99 percent."], "rollback_steps": ["No rollback is possible for an expired certificate; escalate to the certificate authority team if issuance is delayed."]}', N'medium', N'00000000-0000-4000-8000-00000000009f', 1, 1, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000002ed', N'00000000-0000-4000-8000-0000000002de', N'infrastructure', N'Network or platform failure', N'Metrics and platform events are normal; the failure is a certificate validation error rather than a connectivity problem. [E9]', N'1. No saturation or restarts [E9]. 2. Error text names certificate expiry, not network failure.', 0.1, N'[]', N'["E9"]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 2, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-000000000304', N'00000000-0000-4000-8000-0000000002ff', N'application', N'A defect in MetLife-owned configuration of the portal', N'MetLife owns no code in this service and no change was made; an application cause is very unlikely.', N'1. No MetLife-side change near onset. 2. The service is vendor-hosted.', 0.1, N'[]', N'[]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 0, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-000000000305', N'00000000-0000-4000-8000-0000000002ff', N'dependencies', N'The SaaS vendor reports degraded performance in its APAC region', N'The vendor is degraded in its APAC region and synthetic probes from Keigan fail intermittently with HTTP 503.', N'1. A large share of synthetic probes fail with 503. 2. The vendor status page reports degraded performance in the same period.', 0.9, N'[]', N'[]', N'{"summary": "Nothing can be fixed on the Keigan side; track the vendor incident, inform employees and agree an ETA.", "steps": [{"description": "Subscribe to the vendor status page incident and share the link with the incident channel.", "command_text": null, "command_language": null, "command_risk_level": null}, {"description": "Post a banner or intranet notice that enrolment may be slow or unavailable.", "command_text": null, "command_language": null, "command_risk_level": null}, {"description": "Open a priority ticket with the vendor support channel quoting the synthetic probe failure times.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Synthetic probes succeed for three consecutive runs."], "rollback_steps": ["Not applicable: no change is made to MetLife systems."]}', N'medium', N'00000000-0000-4000-8000-0000000000a2', 1, 1, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-000000000306', N'00000000-0000-4000-8000-0000000002ff', N'infrastructure', N'MetLife network path to the vendor', N'Failures are HTTP 503 responses from the vendor, not connection errors, so MetLife networking is unlikely to be involved.', N'1. Responses arrive, so connectivity works. 2. The 503 body comes from the vendor.', 0.1, N'[]', N'[]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 2, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-000000000339', N'00000000-0000-4000-8000-000000000318', N'application', N'Release raised batch import parallelism and exhausted the SQL connection pool', N'A configuration change shortly before onset raised parallel batch imports from 4 to 16 threads. claims-api then ran out of pooled SQL connections and began timing out. [E9] [E2]', N'1. Errors on claims-api are connection acquisition timeouts, a pattern new compared with the baseline [E2]. 2. A configuration change preceded onset by minutes [E9]. 3. claims-sql session usage rose in step with the errors [E1]. The change explains both the new pattern and the timing.', 0.86, N'["E2", "E9", "E1"]', N'[]', N'{"summary": "Restore the previous batch import concurrency, restart the service to release saturated connections, then cap parallelism below the pool size.", "steps": [{"description": "Restore BATCH_IMPORT_PARALLELISM=4 on claims-api.", "command_text": "kubectl set env deployment/claims-api BATCH_IMPORT_PARALLELISM=4 -n claims", "command_language": "bash", "command_risk_level": "medium"}, {"description": "Restart claims-api so new pods pick up the corrected configuration.", "command_text": "kubectl rollout restart deployment/claims-api -n claims", "command_language": "bash", "command_risk_level": "medium"}, {"description": "Confirm SQL sessions are falling back below 60 percent.", "command_text": "az monitor metrics list --resource /subscriptions/8d1c3f2a-4b6e-4c1d-9a7f-21530c1a0001/resourceGroups/RG_21530_CLMJP_PRD01/providers/Microsoft.Sql/servers/databases/claims-sql --metric sessions_percent --interval PT5M --aggregation Maximum", "command_language": "bash", "command_risk_level": "low"}, {"description": "Durable fix: size the connection pool for peak parallelism and reject configuration where parallelism exceeds the pool.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [{"repository_name": "claims-api", "file_path": "file not identified", "change_description": "Cap batch import parallelism at the connection pool size and fail fast at startup when the configuration exceeds it.", "before_snippet": "batch.import.parallelism: 16\nhikari.maximumPoolSize: 10", "after_snippet": "batch.import.parallelism: 4\nhikari.maximumPoolSize: 20  # parallelism must stay below pool size"}], "verification_steps": ["Failed requests on POST /api/claims return to baseline within 10 minutes.", "SQL sessions stay below 60 percent for 30 minutes."], "rollback_steps": ["If errors persist, scale the service back to its previous replica count and reopen the investigation."]}', N'medium', N'00000000-0000-4000-8000-00000000009b', 1, 0, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-00000000033a', N'00000000-0000-4000-8000-000000000318', N'dependencies', N'Azure SQL reached its session limit', N'claims-sql hit its session and request limit, so claims-api could not obtain connections. The database is the place where the failure surfaces, but the evidence points to the caller creating the load. [E1] [E7]', N'1. claims-sql shows elevated sessions [E1] and errors [E4]. 2. However the session growth starts after the configuration change [E9], which makes the database a victim rather than the origin. Confidence is moderate because the saturation itself is real.', 0.52, N'["E1", "E4", "E9"]', N'[]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 1, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-00000000033b', N'00000000-0000-4000-8000-000000000318', N'infrastructure', N'Compute saturation on the claims cluster', N'There is no sign of node, memory or CPU saturation. Infrastructure is unlikely to be the cause. [E22]', N'1. Compute metrics stay within the baseline range [E22]. 2. Nothing in the evidence connects node-level resources to the connection timeouts.', 0.14, N'[]', N'["E22"]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 2, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-000000000361', N'00000000-0000-4000-8000-00000000034d', N'application', N'A mobile release polls the policy summary every 5 seconds', N'A new mobile app release polls the policy summary every 5 seconds instead of 60, multiplying request volume and tripping the gateway rate limit. [E4] [E1]', N'1. Request volume on one operation rose about fourfold [E1]. 2. Throttling messages name the subscription and operation [E3]. 3. The increase matches a client polling change, not organic growth.', 0.68, N'["E1", "E3"]', N'[]', N'{"summary": "Raise the rate limit temporarily to stop user-facing 429 responses, then restore the 60 second polling interval in the mobile app.", "steps": [{"description": "Raise the per-subscription limit in the inbound policy of the mobile policy-summary operation (change process applies).", "command_text": null, "command_language": null, "command_risk_level": null}, {"description": "Ship the mobile hot-fix that restores the 60 second polling interval and add client-side back-off on 429.", "command_text": null, "command_language": null, "command_risk_level": null}, {"description": "After the hot-fix reaches most users, restore the original rate limit.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [{"repository_name": "chad-apim", "file_path": "file not identified", "change_description": "Temporary increase of the rate limit.", "before_snippet": "<rate-limit-by-key calls=\"100\" renewal-period=\"60\" counter-key=\"@(context.Subscription.Id)\" />", "after_snippet": "<rate-limit-by-key calls=\"400\" renewal-period=\"60\" counter-key=\"@(context.Subscription.Id)\" />"}], "verification_steps": ["429 responses drop below 1 percent.", "Request volume per subscription returns to the baseline rate."], "rollback_steps": ["Restore the previous policy revision of the API in API Management."]}', N'medium', N'00000000-0000-4000-8000-00000000009f', 1, 0, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-000000000362', N'00000000-0000-4000-8000-00000000034d', N'dependencies', N'Backend dependency slowness', N'Backend responses are healthy; 429 is generated by the gateway itself. [E14]', N'1. Backend duration is normal [E14]. 2. 429 responses are produced by the gateway.', 0.25, N'[]', N'["E14"]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 1, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-000000000363', N'00000000-0000-4000-8000-00000000034d', N'infrastructure', N'API Management rate-limit policy is too low for current traffic', N'The API Management rate-limit policy returns 429 once a subscription exceeds its quota, and the quota is now too low for the new traffic pattern. [E3]', N'1. The rate-limit policy is working as configured [E3]. 2. Gateway capacity rose to 1.6x but did not saturate [E1]. The policy value is a contributing condition, the load change is the trigger.', 0.62, N'["E3", "E1"]', N'[]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 2, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-00000000038a', N'00000000-0000-4000-8000-000000000375', N'application', N'Retries without jitter amplify the partner slowdown', N'The payment client retries five times without jitter, multiplying the load on a slow partner and exhausting its own outbound HTTP pool. This worsens the incident but is not its trigger. [E3]', N'1. Retry attempts 1 to 5 appear in the logs [E3]. 2. Retries without jitter amplify an external slowdown, but the slowdown existed first [E7].', 0.45, N'["E3", "E7"]', N'[]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 0, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-00000000038b', N'00000000-0000-4000-8000-000000000375', N'dependencies', N'The partner payment gateway is responding in more than 25 seconds', N'The partner bank gateway is timing out calls to its confirm endpoint (more than 25 seconds). Every payment confirmation that depends on it is delayed. [E7] [E3]', N'1. Calls to the partner endpoint time out after 25 s [E3]. 2. Dependency failures are new compared with the baseline [E7]. 3. Latency increased several-fold only on operations that call the partner.', 0.84, N'["E3", "E7"]', N'[]', N'{"summary": "Stop amplifying the partner slowdown: enable the circuit-breaker fallback, add jitter to retries and engage the partner.", "steps": [{"description": "Check the partner endpoint latency from a trusted host (read-only).", "command_text": "curl -s -o /dev/null -w \"%{time_total}s\\n\" https://api.partner-bank.example/payments/v2/health", "command_language": "bash", "command_risk_level": "medium"}, {"description": "Enable the payment gateway circuit-breaker fallback so confirmations are queued instead of retried synchronously.", "command_text": null, "command_language": null, "command_risk_level": null}, {"description": "Raise the incident with the partner bank''s operations contact and share the timeout timestamps from the evidence.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [{"repository_name": "payment-confirmation-func", "file_path": "file not identified", "change_description": "Use exponential back-off with jitter and a total retry budget instead of five immediate retries.", "before_snippet": "Policy.Handle<TaskCanceledException>().WaitAndRetryAsync(5, _ => TimeSpan.FromSeconds(1))", "after_snippet": "Policy.Handle<TaskCanceledException>().WaitAndRetryAsync(Backoff.DecorrelatedJitterBackoffV2(TimeSpan.FromSeconds(2), 3))"}], "verification_steps": ["Outbound HTTP client pool usage falls below 70 percent.", "Confirmation latency returns below 10 seconds once the partner recovers."], "rollback_steps": ["Disable the fallback queue once the partner is healthy and drain deferred confirmations."]}', N'medium', N'00000000-0000-4000-8000-0000000000a0', 1, 1, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-00000000038c', N'00000000-0000-4000-8000-000000000375', N'infrastructure', N'Network or compute limits on the payments platform', N'Platform metrics are in range; nothing suggests the payments platform itself is constrained. [E15]', N'1. CPU, memory and restart counters are normal [E15]. 2. Latency is confined to calls toward the partner.', 0.12, N'[]', N'["E15"]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 2, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000003a6', N'00000000-0000-4000-8000-00000000039e', N'application', N'PBIL0400 abended S0C7 on a malformed packed-decimal premium amount', N'Job PBIL0400 ended with ABEND S0C7 (data exception) in program PBILCALC while processing a premium amount that is not valid packed decimal. [E1]', N'1. IEF450I and $HASP395 both report ABEND=S0C7 for step STEP030 [E1]. 2. S0C7 means arithmetic on invalid packed decimal data. 3. CEE3207S names program PBILCALC.', 0.85, N'["E1"]', N'[]', N'{"summary": "Correct or skip the malformed input record, then restart the job from the failed step as the runbook describes.", "steps": [{"description": "Identify the malformed packed-decimal premium amount in PBIL.INPUT.D1119 from the dump of step STEP030.", "command_text": null, "command_language": null, "command_risk_level": null}, {"description": "Correct or remove the record in a copy of the input data set (data change, requires batch operations approval).", "command_text": null, "command_language": null, "command_risk_level": null}, {"description": "Restart PBIL0400 from STEP030.", "command_text": "//PBIL0400 JOB (ACCT),''PREMIUM BILLING'',RESTART=STEP030", "command_language": "text", "command_risk_level": "low"}, {"description": "Check that downstream statement generation starts and completes.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["PBIL0400 ends with condition code 0000.", "Downstream statements are produced for the billing cycle."], "rollback_steps": ["Keep the original input data set untouched so the run can be repeated."]}', N'medium', N'00000000-0000-4000-8000-0000000000a1', 1, 0, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000003a7', N'00000000-0000-4000-8000-00000000039e', N'dependencies', N'A late or corrupt input feed', N'The malformed record probably originates upstream, so an input feed is a contributing factor. The abend itself is data-driven. [E1]', N'1. A bad value in the input data set had to come from the upstream extract. 2. No evidence shows the feed was late.', 0.3, N'[]', N'[]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 1, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000003a8', N'00000000-0000-4000-8000-00000000039e', N'infrastructure', N'LPAR or storage problem on the mainframe', N'No system-level problem is visible; S0C7 is a data exception, not a resource failure. [E5]', N'1. No storage, CPU or LPAR events [E5]. 2. S0C7 does not indicate resource exhaustion.', 0.12, N'[]', N'["E5"]', N'{"summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"description": "Re-check this lens if the leading hypothesis is disproved.", "command_text": null, "command_language": null, "command_risk_level": null}], "code_changes": [], "verification_steps": ["Confirm the leading hypothesis fix resolves the symptoms."], "rollback_steps": []}', N'low', NULL, 0, 2, '2026-11-20 12:00:00.000000');
INSERT INTO [keigan].[investigation_hypothesis] ([hypothesis_id], [investigation_id], [analysis_perspective], [hypothesis_title], [hypothesis_statement_markdown], [reasoning_markdown], [confidence_score], [supporting_evidence_codes_json], [contradicting_evidence_codes_json], [proposed_fix_json], [fix_risk_level], [matched_runbook_id], [is_leading_hypothesis], [display_order], [created_at])
SELECT [source].[hypothesis_id], [source].[investigation_id], [source].[analysis_perspective], [source].[hypothesis_title], [source].[hypothesis_statement_markdown], [source].[reasoning_markdown], [source].[confidence_score], [source].[supporting_evidence_codes_json], [source].[contradicting_evidence_codes_json], [source].[proposed_fix_json], [source].[fix_risk_level], [source].[matched_runbook_id], [source].[is_leading_hypothesis], [source].[display_order], [source].[created_at] FROM #demo_rows AS [source]
WHERE NOT EXISTS (SELECT 1 FROM [keigan].[investigation_hypothesis] AS [existing] WHERE [existing].[hypothesis_id] = [source].[hypothesis_id]);
DROP TABLE #demo_rows;
GO

DROP TABLE IF EXISTS #demo_rows;
