INSERT INTO #demo_rows ([postmortem_id], [incident_id], [investigation_id], [report_title], [report_markdown], [report_sections_json], [language_code], [report_status], [generation_trigger], [finalized_by_user_principal_name], [finalized_at], [sent_at], [created_at], [updated_at], [created_by_user_principal_name], [updated_by_user_principal_name]) VALUES
    (N'00000000-0000-4000-8000-0000000002db', N'00000000-0000-4000-8000-0000000002ae', N'00000000-0000-4000-8000-0000000002af', N'Postmortem: Claims Processing (JP): intermittent 502 errors and pod restarts', N'# Postmortem: Claims Processing (JP): intermittent 502 errors and pod restarts

## Summary

Parts of Claims Processing (JP) intermittently fail because a service keeps running out of memory and restarting. Users see occasional errors when documents are rendered. A temporary memory increase and restart stabilise it; the underlying memory leak needs a code fix.

## Impact

Claims Processing (JP) was degraded for 29 minutes. Claims Processing (JP) saw intermittent 502 errors while pods of claims-document-renderer restarted repeatedly. Kubernetes reports containers OOMKilled and backing off, and restart counts increased.

## Timeline

| Time | Event |
| --- | --- |
| 2026-11-03 04:33 UTC | Incident INC004090137 opened in ServiceNow |
| 2026-11-03 04:34 UTC | Keigan started investigating |
| 2026-11-03 04:36 UTC | Evidence collected: 24 items, 7 strong |
| 2026-11-03 04:37 UTC | Root cause analysis ready (confidence 82%) |
| 2026-11-03 04:53 UTC | Responder confirmed the proposed fix was applied |
| 2026-11-03 05:02 UTC | Incident resolved |

## Root cause

Containers of claims-document-renderer reach their 1 GiB memory limit and are killed by the kernel [E4]. Memory grows by roughly 300 MB per hour, which indicates a leak in the document renderer rather than a one-off spike. While pods restart the gateway has no healthy backend and returns 502.

## Contributing factors

- Existing alerts did not describe the failing component clearly enough to shorten diagnosis.
- The relevant limit or dependency was not covered by a capacity or readiness check.

## Detection

The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.

## Response

Responders followed the investigation''s proposed fix. Total time to restore service: 29 minutes.

## What went well

- Keigan assembled evidence and a ranked root cause hypothesis before responders joined.
- Stakeholders received bilingual updates early.

## What could be improved

- Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.
- The fix steps were manual and should be rehearsed.

## Action items

| Action | Owner | Due | Type |
| --- | --- | --- | --- |
| Fix the image buffer leak in the document renderer and add a soak test | Claims platform team | 2026-11-24 | prevent |
| Alert when container memory exceeds 80 percent of its limit | Claims SRE team | 2026-11-10 | detect |
| Set pod disruption budgets and a second replica to absorb restarts | Claims platform team | 2026-11-17 | mitigate |

## Lessons learned

- Restarts hide leaks; track memory trend, not only restart counts.', N'{"report_title": "Postmortem: Claims Processing (JP): intermittent 502 errors and pod restarts", "summary": "Parts of Claims Processing (JP) intermittently fail because a service keeps running out of memory and restarting. Users see occasional errors when documents are rendered. A temporary memory increase and restart stabilise it; the underlying memory leak needs a code fix.", "impact": "Claims Processing (JP) was degraded for 29 minutes. Claims Processing (JP) saw intermittent 502 errors while pods of claims-document-renderer restarted repeatedly. Kubernetes reports containers OOMKilled and backing off, and restart counts increased.", "timeline": [{"time_text": "2026-11-03 04:33 UTC", "description": "Incident INC004090137 opened in ServiceNow"}, {"time_text": "2026-11-03 04:34 UTC", "description": "Keigan started investigating"}, {"time_text": "2026-11-03 04:36 UTC", "description": "Evidence collected: 24 items, 7 strong"}, {"time_text": "2026-11-03 04:37 UTC", "description": "Root cause analysis ready (confidence 82%)"}, {"time_text": "2026-11-03 04:53 UTC", "description": "Responder confirmed the proposed fix was applied"}, {"time_text": "2026-11-03 05:02 UTC", "description": "Incident resolved"}], "root_cause": "Containers of claims-document-renderer reach their 1 GiB memory limit and are killed by the kernel [E4]. Memory grows by roughly 300 MB per hour, which indicates a leak in the document renderer rather than a one-off spike. While pods restart the gateway has no healthy backend and returns 502.", "contributing_factors": ["Existing alerts did not describe the failing component clearly enough to shorten diagnosis.", "The relevant limit or dependency was not covered by a capacity or readiness check."], "detection": "The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.", "response": "Responders followed the investigation''s proposed fix. Total time to restore service: 29 minutes.", "what_went_well": ["Keigan assembled evidence and a ranked root cause hypothesis before responders joined.", "Stakeholders received bilingual updates early."], "what_could_be_improved": ["Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.", "The fix steps were manual and should be rehearsed."], "action_items": [{"description": "Fix the image buffer leak in the document renderer and add a soak test", "owner_role": "Claims platform team", "due_in_days": 21, "action_type": "prevent"}, {"description": "Alert when container memory exceeds 80 percent of its limit", "owner_role": "Claims SRE team", "due_in_days": 7, "action_type": "detect"}, {"description": "Set pod disruption budgets and a second replica to absorb restarts", "owner_role": "Claims platform team", "due_in_days": 14, "action_type": "mitigate"}], "lessons_learned": ["Restarts hide leaks; track memory trend, not only restart counts."], "incident_resolved_at": "2026-11-03T05:02:00+00:00"}', N'en', N'final', N'seed', N'keigan.admin@keigan.local', '2026-11-04 05:02:00.000000', '2026-11-04 05:07:00.000000', '2026-11-03 06:02:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', NULL),
    (N'00000000-0000-4000-8000-0000000002fc', N'00000000-0000-4000-8000-0000000002dd', N'00000000-0000-4000-8000-0000000002de', N'Postmortem: Channel APIs for Digital (AU): all calls to the policy core system failing', N'# Postmortem: Channel APIs for Digital (AU): all calls to the policy core system failing

## Summary

A security certificate that Channel APIs for Digital (AU) uses to talk to the policy core system expired at midnight UTC, so most calls fail. A new certificate must be issued and loaded; service returns once it is in place.

## Impact

Channel APIs for Digital (AU) was degraded for 25 minutes. Calls from Channel APIs for Digital (AU) to the policy core system fail with TLS errors, so channel API operations that need policy data are unavailable [E2].

## Timeline

| Time | Event |
| --- | --- |
| 2026-11-07 05:29 UTC | Incident INC004090274 opened in ServiceNow |
| 2026-11-07 05:30 UTC | Keigan started investigating |
| 2026-11-07 05:32 UTC | Evidence collected: 10 items, 6 strong |
| 2026-11-07 05:33 UTC | Root cause analysis ready (confidence 88%) |
| 2026-11-07 05:49 UTC | Responder confirmed the proposed fix was applied |
| 2026-11-07 05:54 UTC | Incident resolved |

## Root cause

The mutual-TLS client certificate used to call the policy core system expired at 00:00 UTC. The first failure appears at that moment and the error text states that the certificate has expired [E2]. No change was deployed, which fits a time-based cause.

## Contributing factors

- Existing alerts did not describe the failing component clearly enough to shorten diagnosis.
- The relevant limit or dependency was not covered by a capacity or readiness check.

## Detection

The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.

## Response

Responders followed the investigation''s proposed fix. Total time to restore service: 25 minutes.

## What went well

- Keigan assembled evidence and a ranked root cause hypothesis before responders joined.
- Stakeholders received bilingual updates early.

## What could be improved

- Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.
- The fix steps were manual and should be rehearsed.

## Action items

| Action | Owner | Due | Type |
| --- | --- | --- | --- |
| Automate certificate renewal and rotation in Key Vault | Platform security team | 2026-12-07 | prevent |
| Alert 30, 14 and 7 days before any certificate expires | Channel SRE team | 2026-11-14 | detect |
| Document the emergency issuance path and its approvers | Platform security team | 2026-11-21 | mitigate |

## Lessons learned

- A certificate inventory with owners and expiry alerts would have prevented a P1.', N'{"report_title": "Postmortem: Channel APIs for Digital (AU): all calls to the policy core system failing", "summary": "A security certificate that Channel APIs for Digital (AU) uses to talk to the policy core system expired at midnight UTC, so most calls fail. A new certificate must be issued and loaded; service returns once it is in place.", "impact": "Channel APIs for Digital (AU) was degraded for 25 minutes. Calls from Channel APIs for Digital (AU) to the policy core system fail with TLS errors, so channel API operations that need policy data are unavailable [E2].", "timeline": [{"time_text": "2026-11-07 05:29 UTC", "description": "Incident INC004090274 opened in ServiceNow"}, {"time_text": "2026-11-07 05:30 UTC", "description": "Keigan started investigating"}, {"time_text": "2026-11-07 05:32 UTC", "description": "Evidence collected: 10 items, 6 strong"}, {"time_text": "2026-11-07 05:33 UTC", "description": "Root cause analysis ready (confidence 88%)"}, {"time_text": "2026-11-07 05:49 UTC", "description": "Responder confirmed the proposed fix was applied"}, {"time_text": "2026-11-07 05:54 UTC", "description": "Incident resolved"}], "root_cause": "The mutual-TLS client certificate used to call the policy core system expired at 00:00 UTC. The first failure appears at that moment and the error text states that the certificate has expired [E2]. No change was deployed, which fits a time-based cause.", "contributing_factors": ["Existing alerts did not describe the failing component clearly enough to shorten diagnosis.", "The relevant limit or dependency was not covered by a capacity or readiness check."], "detection": "The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.", "response": "Responders followed the investigation''s proposed fix. Total time to restore service: 25 minutes.", "what_went_well": ["Keigan assembled evidence and a ranked root cause hypothesis before responders joined.", "Stakeholders received bilingual updates early."], "what_could_be_improved": ["Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.", "The fix steps were manual and should be rehearsed."], "action_items": [{"description": "Automate certificate renewal and rotation in Key Vault", "owner_role": "Platform security team", "due_in_days": 30, "action_type": "prevent"}, {"description": "Alert 30, 14 and 7 days before any certificate expires", "owner_role": "Channel SRE team", "due_in_days": 7, "action_type": "detect"}, {"description": "Document the emergency issuance path and its approvers", "owner_role": "Platform security team", "due_in_days": 14, "action_type": "mitigate"}], "lessons_learned": ["A certificate inventory with owners and expiry alerts would have prevented a P1."], "incident_resolved_at": "2026-11-07T05:54:00+00:00"}', N'en', N'final', N'seed', N'keigan.admin@keigan.local', '2026-11-08 05:54:00.000000', '2026-11-08 05:59:00.000000', '2026-11-07 06:54:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', NULL),
    (N'00000000-0000-4000-8000-000000000315', N'00000000-0000-4000-8000-0000000002fe', N'00000000-0000-4000-8000-0000000002ff', N'Postmortem: Employee Benefits Portal (SaaS): benefits portal slow and intermittently unavailable', N'# Postmortem: Employee Benefits Portal (SaaS): benefits portal slow and intermittently unavailable

## Summary

The benefits portal is slow or unavailable because our vendor is having a service problem in the Asia-Pacific region. We are tracking the vendor''s incident and will update employees when it is resolved.

## Impact

Employee Benefits Portal (SaaS) was degraded for 74 minutes. Employees cannot reliably open the benefits portal of Employee Benefits Portal (SaaS); Keigan''s synthetic probe fails about 40 percent of the time with HTTP 503.

## Timeline

| Time | Event |
| --- | --- |
| 2026-11-11 06:25 UTC | Incident INC004090822 opened in ServiceNow |
| 2026-11-11 06:26 UTC | Keigan started investigating |
| 2026-11-11 06:28 UTC | Evidence collected: 2 items, 0 strong |
| 2026-11-11 06:29 UTC | Root cause analysis ready (confidence 90%) |
| 2026-11-11 06:45 UTC | Responder confirmed the proposed fix was applied |
| 2026-11-11 07:39 UTC | Incident resolved |

## Root cause

The SaaS vendor is experiencing degraded performance in its APAC region, which its status page confirms, and our probes see HTTP 503 and multi-second latency. No MetLife change is involved.

## Contributing factors

- Existing alerts did not describe the failing component clearly enough to shorten diagnosis.
- The relevant limit or dependency was not covered by a capacity or readiness check.

## Detection

The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.

## Response

Responders followed the investigation''s proposed fix. Total time to restore service: 74 minutes.

## What went well

- Keigan assembled evidence and a ranked root cause hypothesis before responders joined.
- Stakeholders received bilingual updates early.

## What could be improved

- Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.
- The fix steps were manual and should be rehearsed.

## Action items

| Action | Owner | Due | Type |
| --- | --- | --- | --- |
| Negotiate a vendor SLA with regional failover and incident notification commitments | Vendor management | 2027-01-10 | prevent |
| Subscribe operations to the vendor status feed so incidents are known within minutes | Benefits SRE team | 2026-11-18 | detect |
| Prepare a standard employee notice template for vendor outages | Benefits platform team | 2026-11-25 | mitigate |

## Lessons learned

- For vendor-hosted services, detection and communication are our main levers.', N'{"report_title": "Postmortem: Employee Benefits Portal (SaaS): benefits portal slow and intermittently unavailable", "summary": "The benefits portal is slow or unavailable because our vendor is having a service problem in the Asia-Pacific region. We are tracking the vendor''s incident and will update employees when it is resolved.", "impact": "Employee Benefits Portal (SaaS) was degraded for 74 minutes. Employees cannot reliably open the benefits portal of Employee Benefits Portal (SaaS); Keigan''s synthetic probe fails about 40 percent of the time with HTTP 503.", "timeline": [{"time_text": "2026-11-11 06:25 UTC", "description": "Incident INC004090822 opened in ServiceNow"}, {"time_text": "2026-11-11 06:26 UTC", "description": "Keigan started investigating"}, {"time_text": "2026-11-11 06:28 UTC", "description": "Evidence collected: 2 items, 0 strong"}, {"time_text": "2026-11-11 06:29 UTC", "description": "Root cause analysis ready (confidence 90%)"}, {"time_text": "2026-11-11 06:45 UTC", "description": "Responder confirmed the proposed fix was applied"}, {"time_text": "2026-11-11 07:39 UTC", "description": "Incident resolved"}], "root_cause": "The SaaS vendor is experiencing degraded performance in its APAC region, which its status page confirms, and our probes see HTTP 503 and multi-second latency. No MetLife change is involved.", "contributing_factors": ["Existing alerts did not describe the failing component clearly enough to shorten diagnosis.", "The relevant limit or dependency was not covered by a capacity or readiness check."], "detection": "The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.", "response": "Responders followed the investigation''s proposed fix. Total time to restore service: 74 minutes.", "what_went_well": ["Keigan assembled evidence and a ranked root cause hypothesis before responders joined.", "Stakeholders received bilingual updates early."], "what_could_be_improved": ["Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.", "The fix steps were manual and should be rehearsed."], "action_items": [{"description": "Negotiate a vendor SLA with regional failover and incident notification commitments", "owner_role": "Vendor management", "due_in_days": 60, "action_type": "prevent"}, {"description": "Subscribe operations to the vendor status feed so incidents are known within minutes", "owner_role": "Benefits SRE team", "due_in_days": 7, "action_type": "detect"}, {"description": "Prepare a standard employee notice template for vendor outages", "owner_role": "Benefits platform team", "due_in_days": 14, "action_type": "mitigate"}], "lessons_learned": ["For vendor-hosted services, detection and communication are our main levers."], "incident_resolved_at": "2026-11-11T07:39:00+00:00"}', N'en', N'final', N'seed', N'keigan.admin@keigan.local', '2026-11-12 07:39:00.000000', '2026-11-12 07:44:00.000000', '2026-11-11 08:39:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', NULL),
    (N'00000000-0000-4000-8000-00000000034a', N'00000000-0000-4000-8000-000000000317', N'00000000-0000-4000-8000-000000000318', N'Postmortem: Claims Processing (JP): claim submissions failing with timeouts', N'# Postmortem: Claims Processing (JP): claim submissions failing with timeouts

## Summary

Claim submissions in Claims Processing (JP) are failing because a recent configuration change overloaded the claims database connections. Customers see long waits and errors when submitting claims. The change can be reverted and the service restarted; recovery is expected within minutes of doing so.

## Impact

Claims Processing (JP) was degraded for 42 minutes. Claim submissions on Claims Processing (JP) began failing with timeouts. Error patterns on claims-api that did not exist before the incident ([E2]) show requests waiting for a database connection until they time out, and claims-sql was running at its session limit [E1].

## Timeline

| Time | Event |
| --- | --- |
| 2026-11-14 01:10 UTC | Routine release 2026.11.14.1 deployed |
| 2026-11-14 03:09 UTC | App setting BATCH_IMPORT_PARALLELISM changed from 4 to 16 (release 2026.11.18.2) |
| 2026-11-14 03:22 UTC | Incident INC004090000 opened in ServiceNow |
| 2026-11-14 03:23 UTC | Keigan started investigating |
| 2026-11-14 03:25 UTC | Evidence collected: 27 items, 10 strong |
| 2026-11-14 03:26 UTC | Root cause analysis ready (confidence 86%) |
| 2026-11-14 03:42 UTC | Responder confirmed the proposed fix was applied |
| 2026-11-14 04:04 UTC | Incident resolved |
| 2026-11-20 12:00 UTC | The incident text contained instruction-like content, which Keigan ignored |

## Root cause

A configuration change raised batch import parallelism from 4 to 16 [E9]. Each import thread holds a database connection, so the connection pool of claims-api was exhausted and normal requests queued behind the imports [E2]. claims-sql reached its session limit as a result [E1]. Timing of the change, the first errors and the session growth line up within minutes.

## Contributing factors

- Existing alerts did not describe the failing component clearly enough to shorten diagnosis.
- The relevant limit or dependency was not covered by a capacity or readiness check.

## Detection

The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.

## Response

Responders followed the investigation''s proposed fix. Total time to restore service: 42 minutes.

## What went well

- Keigan assembled evidence and a ranked root cause hypothesis before responders joined.
- Stakeholders received bilingual updates early.

## What could be improved

- Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.
- The fix steps were manual and should be rehearsed.

## Action items

| Action | Owner | Due | Type |
| --- | --- | --- | --- |
| Add a startup validation that rejects batch parallelism greater than the connection pool size | Claims platform team | 2026-11-28 | prevent |
| Alert when SQL sessions exceed 80 percent for 5 minutes | Claims SRE team | 2026-11-21 | detect |
| Document and rehearse reverting configuration releases within 10 minutes | Claims platform team | 2026-12-05 | mitigate |

## Lessons learned

- Configuration changes can be as risky as code changes and need the same capacity review.', N'{"report_title": "Postmortem: Claims Processing (JP): claim submissions failing with timeouts", "summary": "Claim submissions in Claims Processing (JP) are failing because a recent configuration change overloaded the claims database connections. Customers see long waits and errors when submitting claims. The change can be reverted and the service restarted; recovery is expected within minutes of doing so.", "impact": "Claims Processing (JP) was degraded for 42 minutes. Claim submissions on Claims Processing (JP) began failing with timeouts. Error patterns on claims-api that did not exist before the incident ([E2]) show requests waiting for a database connection until they time out, and claims-sql was running at its session limit [E1].", "timeline": [{"time_text": "2026-11-14 01:10 UTC", "description": "Routine release 2026.11.14.1 deployed"}, {"time_text": "2026-11-14 03:09 UTC", "description": "App setting BATCH_IMPORT_PARALLELISM changed from 4 to 16 (release 2026.11.18.2)"}, {"time_text": "2026-11-14 03:22 UTC", "description": "Incident INC004090000 opened in ServiceNow"}, {"time_text": "2026-11-14 03:23 UTC", "description": "Keigan started investigating"}, {"time_text": "2026-11-14 03:25 UTC", "description": "Evidence collected: 27 items, 10 strong"}, {"time_text": "2026-11-14 03:26 UTC", "description": "Root cause analysis ready (confidence 86%)"}, {"time_text": "2026-11-14 03:42 UTC", "description": "Responder confirmed the proposed fix was applied"}, {"time_text": "2026-11-14 04:04 UTC", "description": "Incident resolved"}, {"time_text": "2026-11-20 12:00 UTC", "description": "The incident text contained instruction-like content, which Keigan ignored"}], "root_cause": "A configuration change raised batch import parallelism from 4 to 16 [E9]. Each import thread holds a database connection, so the connection pool of claims-api was exhausted and normal requests queued behind the imports [E2]. claims-sql reached its session limit as a result [E1]. Timing of the change, the first errors and the session growth line up within minutes.", "contributing_factors": ["Existing alerts did not describe the failing component clearly enough to shorten diagnosis.", "The relevant limit or dependency was not covered by a capacity or readiness check."], "detection": "The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.", "response": "Responders followed the investigation''s proposed fix. Total time to restore service: 42 minutes.", "what_went_well": ["Keigan assembled evidence and a ranked root cause hypothesis before responders joined.", "Stakeholders received bilingual updates early."], "what_could_be_improved": ["Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.", "The fix steps were manual and should be rehearsed."], "action_items": [{"description": "Add a startup validation that rejects batch parallelism greater than the connection pool size", "owner_role": "Claims platform team", "due_in_days": 14, "action_type": "prevent"}, {"description": "Alert when SQL sessions exceed 80 percent for 5 minutes", "owner_role": "Claims SRE team", "due_in_days": 7, "action_type": "detect"}, {"description": "Document and rehearse reverting configuration releases within 10 minutes", "owner_role": "Claims platform team", "due_in_days": 21, "action_type": "mitigate"}], "lessons_learned": ["Configuration changes can be as risky as code changes and need the same capacity review."], "incident_resolved_at": "2026-11-14T04:04:00+00:00"}', N'en', N'final', N'seed', N'keigan.admin@keigan.local', '2026-11-15 04:04:00.000000', '2026-11-15 04:09:00.000000', '2026-11-14 05:04:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', NULL),
    (N'00000000-0000-4000-8000-000000000372', N'00000000-0000-4000-8000-00000000034c', N'00000000-0000-4000-8000-00000000034d', N'Postmortem: Channel APIs for Digital (AU): mobile app users receiving ''too many requests''', N'# Postmortem: Channel APIs for Digital (AU): mobile app users receiving ''too many requests''

## Summary

Users of the mobile app in Channel APIs for Digital (AU) are being blocked by a request limit after a new app release started contacting our service far more often. We can raise the limit temporarily and the app team will release a fix.

## Impact

Channel APIs for Digital (AU) was degraded for 49 minutes. Mobile app users of Channel APIs for Digital (AU) see "too many requests" when opening the policy summary. The gateway returned HTTP 429 at a much higher rate than before [E4] [E3].

## Timeline

| Time | Event |
| --- | --- |
| 2026-11-16 06:20 UTC | Incident INC004090411 opened in ServiceNow |
| 2026-11-16 06:21 UTC | Keigan started investigating |
| 2026-11-16 06:23 UTC | Evidence collected: 17 items, 4 strong |
| 2026-11-16 06:24 UTC | Root cause analysis ready (confidence 68%) |
| 2026-11-16 06:40 UTC | Responder confirmed the proposed fix was applied |
| 2026-11-16 07:09 UTC | Incident resolved |

## Root cause

Request volume to the policy summary operation rose about fourfold [E1], consistent with a mobile release that polls every 5 seconds instead of 60. The API Management rate-limit policy then rejected requests over quota with 429 [E3].

## Contributing factors

- Existing alerts did not describe the failing component clearly enough to shorten diagnosis.
- The relevant limit or dependency was not covered by a capacity or readiness check.

## Detection

The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.

## Response

Responders followed the investigation''s proposed fix. Total time to restore service: 49 minutes.

## What went well

- Keigan assembled evidence and a ranked root cause hypothesis before responders joined.
- Stakeholders received bilingual updates early.

## What could be improved

- Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.
- The fix steps were manual and should be rehearsed.

## Action items

| Action | Owner | Due | Type |
| --- | --- | --- | --- |
| Add client-side back-off on HTTP 429 in the mobile app | Mobile app team | 2026-11-30 | prevent |
| Alert on a sudden rise in per-subscription request rate | Channel SRE team | 2026-11-23 | detect |
| Document how to raise API Management rate limits safely | Channel platform team | 2026-11-30 | mitigate |

## Lessons learned

- Client release notes should state any change in polling or request frequency.', N'{"report_title": "Postmortem: Channel APIs for Digital (AU): mobile app users receiving ''too many requests''", "summary": "Users of the mobile app in Channel APIs for Digital (AU) are being blocked by a request limit after a new app release started contacting our service far more often. We can raise the limit temporarily and the app team will release a fix.", "impact": "Channel APIs for Digital (AU) was degraded for 49 minutes. Mobile app users of Channel APIs for Digital (AU) see \"too many requests\" when opening the policy summary. The gateway returned HTTP 429 at a much higher rate than before [E4] [E3].", "timeline": [{"time_text": "2026-11-16 06:20 UTC", "description": "Incident INC004090411 opened in ServiceNow"}, {"time_text": "2026-11-16 06:21 UTC", "description": "Keigan started investigating"}, {"time_text": "2026-11-16 06:23 UTC", "description": "Evidence collected: 17 items, 4 strong"}, {"time_text": "2026-11-16 06:24 UTC", "description": "Root cause analysis ready (confidence 68%)"}, {"time_text": "2026-11-16 06:40 UTC", "description": "Responder confirmed the proposed fix was applied"}, {"time_text": "2026-11-16 07:09 UTC", "description": "Incident resolved"}], "root_cause": "Request volume to the policy summary operation rose about fourfold [E1], consistent with a mobile release that polls every 5 seconds instead of 60. The API Management rate-limit policy then rejected requests over quota with 429 [E3].", "contributing_factors": ["Existing alerts did not describe the failing component clearly enough to shorten diagnosis.", "The relevant limit or dependency was not covered by a capacity or readiness check."], "detection": "The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.", "response": "Responders followed the investigation''s proposed fix. Total time to restore service: 49 minutes.", "what_went_well": ["Keigan assembled evidence and a ranked root cause hypothesis before responders joined.", "Stakeholders received bilingual updates early."], "what_could_be_improved": ["Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.", "The fix steps were manual and should be rehearsed."], "action_items": [{"description": "Add client-side back-off on HTTP 429 in the mobile app", "owner_role": "Mobile app team", "due_in_days": 14, "action_type": "prevent"}, {"description": "Alert on a sudden rise in per-subscription request rate", "owner_role": "Channel SRE team", "due_in_days": 7, "action_type": "detect"}, {"description": "Document how to raise API Management rate limits safely", "owner_role": "Channel platform team", "due_in_days": 14, "action_type": "mitigate"}], "lessons_learned": ["Client release notes should state any change in polling or request frequency."], "incident_resolved_at": "2026-11-16T07:09:00+00:00"}', N'en', N'final', N'seed', N'keigan.admin@keigan.local', '2026-11-17 07:09:00.000000', '2026-11-17 07:14:00.000000', '2026-11-16 08:09:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', NULL),
    (N'00000000-0000-4000-8000-00000000039b', N'00000000-0000-4000-8000-000000000374', N'00000000-0000-4000-8000-000000000375', N'Postmortem: Payments Platform (AU): payment confirmations delayed', N'# Postmortem: Payments Platform (AU): payment confirmations delayed

## Summary

Payment confirmations in Payments Platform (AU) are delayed because our partner bank''s service is responding very slowly. Payments are not lost but confirmations arrive late. We are engaging the partner and changing how our system retries so it does not add load.

## Impact

Payments Platform (AU) was degraded for 64 minutes. Payment confirmations in Payments Platform (AU) are delayed by minutes. Outbound calls to the partner payment gateway time out after about 25 seconds [E3], and dependency failures to that target are new [E7].

## Timeline

| Time | Event |
| --- | --- |
| 2026-11-17 05:19 UTC | Incident INC004090548 opened in ServiceNow |
| 2026-11-17 05:20 UTC | Keigan started investigating |
| 2026-11-17 05:22 UTC | Evidence collected: 18 items, 8 strong |
| 2026-11-17 05:23 UTC | Root cause analysis ready (confidence 84%) |
| 2026-11-17 05:39 UTC | Responder confirmed the proposed fix was applied |
| 2026-11-17 06:23 UTC | Incident resolved |

## Root cause

The partner bank gateway slowed down. payment-confirmation-func retries each call up to five times without jitter, which amplifies load and exhausts the outbound HTTP client pool [E3]. The partner slowdown is the trigger; the retry design makes the effect worse and longer.

## Contributing factors

- Existing alerts did not describe the failing component clearly enough to shorten diagnosis.
- The relevant limit or dependency was not covered by a capacity or readiness check.

## Detection

The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.

## Response

Responders followed the investigation''s proposed fix. Total time to restore service: 64 minutes.

## What went well

- Keigan assembled evidence and a ranked root cause hypothesis before responders joined.
- Stakeholders received bilingual updates early.

## What could be improved

- Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.
- The fix steps were manual and should be rehearsed.

## Action items

| Action | Owner | Due | Type |
| --- | --- | --- | --- |
| Add jitter and a total retry budget to the payment gateway client | Payments platform team | 2026-12-01 | prevent |
| Alert on partner call latency p95 above 10 seconds | Payments SRE team | 2026-11-24 | detect |
| Add a circuit-breaker fallback that queues confirmations | Payments platform team | 2026-12-17 | mitigate |

## Lessons learned

- Retries are load; unbounded retries convert a partner slowdown into our own outage.', N'{"report_title": "Postmortem: Payments Platform (AU): payment confirmations delayed", "summary": "Payment confirmations in Payments Platform (AU) are delayed because our partner bank''s service is responding very slowly. Payments are not lost but confirmations arrive late. We are engaging the partner and changing how our system retries so it does not add load.", "impact": "Payments Platform (AU) was degraded for 64 minutes. Payment confirmations in Payments Platform (AU) are delayed by minutes. Outbound calls to the partner payment gateway time out after about 25 seconds [E3], and dependency failures to that target are new [E7].", "timeline": [{"time_text": "2026-11-17 05:19 UTC", "description": "Incident INC004090548 opened in ServiceNow"}, {"time_text": "2026-11-17 05:20 UTC", "description": "Keigan started investigating"}, {"time_text": "2026-11-17 05:22 UTC", "description": "Evidence collected: 18 items, 8 strong"}, {"time_text": "2026-11-17 05:23 UTC", "description": "Root cause analysis ready (confidence 84%)"}, {"time_text": "2026-11-17 05:39 UTC", "description": "Responder confirmed the proposed fix was applied"}, {"time_text": "2026-11-17 06:23 UTC", "description": "Incident resolved"}], "root_cause": "The partner bank gateway slowed down. payment-confirmation-func retries each call up to five times without jitter, which amplifies load and exhausts the outbound HTTP client pool [E3]. The partner slowdown is the trigger; the retry design makes the effect worse and longer.", "contributing_factors": ["Existing alerts did not describe the failing component clearly enough to shorten diagnosis.", "The relevant limit or dependency was not covered by a capacity or readiness check."], "detection": "The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.", "response": "Responders followed the investigation''s proposed fix. Total time to restore service: 64 minutes.", "what_went_well": ["Keigan assembled evidence and a ranked root cause hypothesis before responders joined.", "Stakeholders received bilingual updates early."], "what_could_be_improved": ["Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.", "The fix steps were manual and should be rehearsed."], "action_items": [{"description": "Add jitter and a total retry budget to the payment gateway client", "owner_role": "Payments platform team", "due_in_days": 14, "action_type": "prevent"}, {"description": "Alert on partner call latency p95 above 10 seconds", "owner_role": "Payments SRE team", "due_in_days": 7, "action_type": "detect"}, {"description": "Add a circuit-breaker fallback that queues confirmations", "owner_role": "Payments platform team", "due_in_days": 30, "action_type": "mitigate"}], "lessons_learned": ["Retries are load; unbounded retries convert a partner slowdown into our own outage."], "incident_resolved_at": "2026-11-17T06:23:00+00:00"}', N'en', N'draft', N'seed', NULL, NULL, NULL, '2026-11-17 07:23:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', NULL),
    (N'00000000-0000-4000-8000-0000000003b7', N'00000000-0000-4000-8000-00000000039d', N'00000000-0000-4000-8000-00000000039e', N'Postmortem: Policy Administration Mainframe (US): nightly premium billing batch did not complete', N'# Postmortem: Policy Administration Mainframe (US): nightly premium billing batch did not complete

## Summary

The nightly premium billing run in Policy Administration Mainframe (US) stopped part-way because one input record is malformed. Statements for the billing cycle are delayed until the record is corrected and the job is restarted from the failed step.

## Impact

Policy Administration Mainframe (US) was degraded for 89 minutes. The nightly premium billing batch for Policy Administration Mainframe (US) did not complete: job PBIL0400 abended in step STEP030 [E1], so downstream statements were not produced.

## Timeline

| Time | Event |
| --- | --- |
| 2026-11-18 04:18 UTC | Incident INC004090685 opened in ServiceNow |
| 2026-11-18 04:19 UTC | Keigan started investigating |
| 2026-11-18 04:21 UTC | Evidence collected: 5 items, 2 strong |
| 2026-11-18 04:22 UTC | Root cause analysis ready (confidence 85%) |
| 2026-11-18 04:38 UTC | Responder confirmed the proposed fix was applied |
| 2026-11-18 05:47 UTC | Incident resolved |

## Root cause

PBIL0400 abended with S0C7, a data exception, in program PBILCALC [E1]. This happens when the program does arithmetic on a field that is not valid packed decimal, most likely a malformed premium amount in the input data set.

## Contributing factors

- Existing alerts did not describe the failing component clearly enough to shorten diagnosis.
- The relevant limit or dependency was not covered by a capacity or readiness check.

## Detection

The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.

## Response

Responders followed the investigation''s proposed fix. Total time to restore service: 89 minutes.

## What went well

- Keigan assembled evidence and a ranked root cause hypothesis before responders joined.
- Stakeholders received bilingual updates early.

## What could be improved

- Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.
- The fix steps were manual and should be rehearsed.

## Action items

| Action | Owner | Due | Type |
| --- | --- | --- | --- |
| Validate packed-decimal fields in the input extract before the billing job starts | Premium billing team | 2026-12-09 | prevent |
| Alert operations within 5 minutes of any ABEND in the billing chain | Mainframe operations | 2026-11-25 | detect |
| Document the restart procedure from STEP030 including data correction approval | Premium billing team | 2026-12-02 | mitigate |

## Lessons learned

- Data validation at the start of the batch chain is cheaper than a restart at 3 a.m.', N'{"report_title": "Postmortem: Policy Administration Mainframe (US): nightly premium billing batch did not complete", "summary": "The nightly premium billing run in Policy Administration Mainframe (US) stopped part-way because one input record is malformed. Statements for the billing cycle are delayed until the record is corrected and the job is restarted from the failed step.", "impact": "Policy Administration Mainframe (US) was degraded for 89 minutes. The nightly premium billing batch for Policy Administration Mainframe (US) did not complete: job PBIL0400 abended in step STEP030 [E1], so downstream statements were not produced.", "timeline": [{"time_text": "2026-11-18 04:18 UTC", "description": "Incident INC004090685 opened in ServiceNow"}, {"time_text": "2026-11-18 04:19 UTC", "description": "Keigan started investigating"}, {"time_text": "2026-11-18 04:21 UTC", "description": "Evidence collected: 5 items, 2 strong"}, {"time_text": "2026-11-18 04:22 UTC", "description": "Root cause analysis ready (confidence 85%)"}, {"time_text": "2026-11-18 04:38 UTC", "description": "Responder confirmed the proposed fix was applied"}, {"time_text": "2026-11-18 05:47 UTC", "description": "Incident resolved"}], "root_cause": "PBIL0400 abended with S0C7, a data exception, in program PBILCALC [E1]. This happens when the program does arithmetic on a field that is not valid packed decimal, most likely a malformed premium amount in the input data set.", "contributing_factors": ["Existing alerts did not describe the failing component clearly enough to shorten diagnosis.", "The relevant limit or dependency was not covered by a capacity or readiness check."], "detection": "The incident was raised in ServiceNow and picked up by Keigan, which started the investigation immediately and collected evidence within minutes.", "response": "Responders followed the investigation''s proposed fix. Total time to restore service: 89 minutes.", "what_went_well": ["Keigan assembled evidence and a ranked root cause hypothesis before responders joined.", "Stakeholders received bilingual updates early."], "what_could_be_improved": ["Detection depended on a user-visible symptom; an earlier signal would shorten time to detect.", "The fix steps were manual and should be rehearsed."], "action_items": [{"description": "Validate packed-decimal fields in the input extract before the billing job starts", "owner_role": "Premium billing team", "due_in_days": 21, "action_type": "prevent"}, {"description": "Alert operations within 5 minutes of any ABEND in the billing chain", "owner_role": "Mainframe operations", "due_in_days": 7, "action_type": "detect"}, {"description": "Document the restart procedure from STEP030 including data correction approval", "owner_role": "Premium billing team", "due_in_days": 14, "action_type": "mitigate"}], "lessons_learned": ["Data validation at the start of the batch chain is cheaper than a restart at 3 a.m."], "incident_resolved_at": "2026-11-18T05:47:00+00:00"}', N'en', N'draft', N'seed', NULL, NULL, NULL, '2026-11-18 06:47:00.000000', '2026-11-20 12:00:00.000000', N'system:seed', NULL);
